, dict) and data.get('statementDate'):\n        today = datetime.date.fromisoformat(str(vars.get('now'))[:10])\n        l4 = data.get('cardNumberLast4') or vars.get('card_last4')\n        nm = (data.get('productName') or '').strip()\n        who = 'Sonu ' + sp(l4) + ' ile biten ' + (nm + ' ' if nm else '') + 'kartınıza ait'\n        stdate = data.get('statementDate')\n        sent = []\n        clear = []\n        for cur, key, name in (('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')):\n            x = data.get(key)\n            if not isinstance(x, dict) or not x:\n                continue\n            rd = float(x.get('remainingDebt') or 0)\n            if rd <= 0:\n                clear.append(name)\n                continue\n            sd = x.get('statementDebt')\n            mn = float(x.get('minPayment') or 0)\n            rm = float(x.get('remainingMinPayment') or 0)\n            if cur == 'TL':\n                if rm > 0 and rm >= mn:\n                    s = name + ' borcunuz ' + amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + '.'\n                elif rm <= 0:\n                    s = name + ' borcunuz ' + amt(sd, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'\n                else:\n                    s = name + ' borcunuz ' + amt(sd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', kalan minimum ödeme tutarınız ' + amt(rm, cur) + '.'\n            else:\n                s = name + ' borcunuz ' + amt(sd, cur) + ', kalan toplam borcunuz ' + amt(rd, cur) + ', ödenmesi gereken minimum tutar ' + amt(mn, cur) + '.'\n            sent.append(s)\n        tl = data.get('debtTL') or {}\n        total_tl = amt(max(float(tl.get('totalDebt') or 0), 0), 'TL')\n        due = dd(data.get('lastPayDate'))\n        cut = dd(stdate)\n        if cut == today:\n            txt = 'Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek. Toplam borcunuz ' + total_tl + '.'\n        elif not sent:\n            txt = 'Sonu ' + sp(l4) + ' ile biten ' + (nm + ' ' if nm else '') + 'kartınızın ' + dt(stdate) + ' tarihli ekstresinden borcunuz bulunmamaktadır. Gelecek dönemler dahil toplam borcunuz ' + total_tl + '. Son ödeme tarihiniz ' + dt(data.get('lastPayDate')) + ' olacaktır.'\n        else:\n            sent[0] = who + ' ' + dt(stdate) + ' tarihinde kesilen ekstre ' + sent[0]\n            if clear:\n                sent.append((clear[0] if len(clear) == 1 else ', '.join(clear[:-1]) + ' ve ' + clear[-1]) + ' borcunuz bulunmamaktadır.')\n            if due < today and str(data.get('automaticPaymentFlag')) == 'Y' and float(data.get('remainAutomaticPaymentAmount') or 0) > 0:\n                sent.append('Otomatik ödeme talimatınızdan çekilecek kalan tutar ' + amt(data.get('remainAutomaticPaymentAmount'), 'TL') + '.')\n            if due == today:\n                sent.append('Borçlarınız için son ödeme tarihiniz bugündür.')\n            elif due < today:\n                sent.append('Son ödeme tarihiniz geçti. Toplam borcunuz ' + total_tl + '.')\n            else:\n                y = dt(data.get('lastPayDate'))\n                sent.append('Borçlarınız için son ödeme tarihiniz ' + y + \"'\" + SUF[y[-1]] + '.')\n            txt = ' '.join(sent)\n        vars['reading_text'] = txt\n        vars['card_last4'] = str(l4)\n        vars['card_name'] = nm\n        vars['balance_state'] = 'ok'\nexcept Exception:\n    vars['balance_state'] = 'error'\n"
