     "post_process_code": "import json\nimport datetime\nO = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']\nT = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']\nMO = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']\nSUF = {'0': 'dır', '1': 'dir', '2': 'dir', '3': 'tür', '4': 'tür', '5': 'tir', '6': 'dır', '7': 'dir', '8': 'dir', '9': 'dur'}\ndef three(n):\n    p = []\n    h = n // 100\n    if h:\n        p.append(('' if h == 1 else O[h] + ' ') + 'yüz')\n    if (n // 10) % 10:\n        p.append(T[(n // 10) % 10])\n    if n % 10:\n        p.append(O[n % 10])\n    return ' '.join(p)\ndef words(n):\n    n = int(n)\n    if n == 0:\n        return 'sıfır'\n    out = []\n    for div, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):\n        q = n // div\n        n = n % div\n        if q:\n            out.append('bin' if (div == 1000 and q == 1) else three(q) + ' ' + name)\n    if n:\n        out.append(three(n))\n    return ' '.join(out)\ndef amt(v, cur):\n    v = round(abs(float(v or 0)), 2)\n    a = int(v)\n    k = int(round((v - a) * 100))\n    if k >= 100:\n        a += 1\n        k = 0\n    if cur == 'TL':\n        return words(a) + (' lira ' + words(k) + ' kuruş' if k else ' Türk Lirası')\n    nm = {'USD': 'dolar', 'EUR': 'euro', 'GBP': 'İngiliz Sterlini'}[cur]\n    cn = 'peni' if cur == 'GBP' else 'sent'\n    return words(a) + ' ' + nm + (' ' + words(k) + ' ' + cn if k else '')\ndef dt(s):\n    d, m, y = str(s).split('.')\n    return str(int(d)) + ' ' + MO[int(m) - 1] + ' ' + y\ndef dd(s):\n    d, m, y = str(s).split('.')\n    return datetime.date(int(y), int(m), int(d))\ndef sp(s):\n    return ' '.join(O[int(c)] if c != '0' else 'sıfır' for c in str(s) if c.isdigit())\ntry:\n    vars['balance_state'] = 'error'\n    b = result.get('data')\n    data = b.get('data') if isinstance(b, dict) else None\n    if isinstance(data