     "post_process_code": "try:\n    b = result.get('data')\n    data = b.get('data') if isinstance(b, dict) else None\n    if isinstance(data, dict) and str(data.get('exitState')).upper() == 'DONE':\n        vars['send_count'] = str(int(vars.get('send_count') or 0) + 1)\n        data['what_to_do_next'] = 'Say exactly: Ekstreniz kayıtlı e-posta adresinize gönderildi. Sizi ana menüye yönlendiriyorum. Then call end_call.'\n    elif isinstance(b, dict):\n        b['what_to_do_next'] = 'It was not sent. Say exactly: Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum. Then call end_call. Do not say it was sent.'\nexcept Exception:\n    pass\n"
     },
    {"type": "function", "config": {"timeoutMs": 10000}, "function": {"name": "end_call", "handler": "__function__:end_call", "description": "Ends the call. CALL it right after you said the closing sentence, with no other text.", "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}
   ],
   "extraction_schema": [
    {"name": "again_card", "type": "string", "enum_values": ["stay", "yes"], "description": "yes when the caller wants to hear the debt of another (or a different) card of theirs, else stay.", "min_confidence": 0.7}
   ],
   "max_node_turns": 30,
   "max_turn_transition": "end_agent_error",
   "transitions": [
    {"target_node": "choose_reset", "description": "Another card", "condition": {"logic": "or", "conditions": [{"variable": "again_card", "operator": "equals", "operand": "yes"}]}}
   ]
  },
  "choose_reset": {
   "name": "choose_reset",
   "node_type": "code",
   "passthrough": true,
   "passthrough_default_transition": "choose",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "pre_actions": [
    {
     "type": "function",
     "function": {
      "name": "code_exec",
      "handler": "__function__:code_exec",
      "parameters": {
       "type": "object",
       "properties": {
        "code": {"type": "string", "default": "try:\n    vars['again_card'] = 'stay'\n    vars['card_choice'] = '0'\nexcept Exception:\n    pass\n"},
        "timeout_ms": {"type": "number", "default": 10000}
       }
      }
     }
    }
   ],
   "transitions": [
    {"target_node": "choose", "description": "always", "condition": {"operator": "always"}}
   ]
  },
  "end_nocard": {
   "name": "end_nocard",
   "node_type": "end_call",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "transitions": [],
   "terminal": {
    "type": "function",
    "function": {
     "name": "main_menu_no_card",
     "handler": "__function__:end_call",
     "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": "Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum."}}}
    }
   }
  },
  "end_agent_error": {
   "name": "end_agent_error",
   "node_type": "end_call",
   "on_enter": {"type": "silent"},
   "disable_inactivity_monitor": true,
   "transitions": [],
   "terminal": {
    "type": "function",
    "function": {
     "name": "agent_service_error",
     "handler": "__function__:end_call",
     "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": "Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum."}}}
    }
   }
  }
 }
}

