     "post_process_code": "import json\nO = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']\ndef sp(s):\n    return ' '.join(O[int(c)] if c != '0' else 'sıfır' for c in str(s) if c.isdigit())\ntry:\n    vars['route'] = 'error'\n    b = result.get('data')\n    data = b.get('data') if isinstance(b, dict) else None\n    code = str((b.get('result') or {}).get('code')) if isinstance(b, dict) and isinstance(b.get('result'), dict) else ''\n    if isinstance(data, dict) and isinstance(data.get('cards'), list):\n        cards = [c for c in data['cards'] if str(c.get('isMainCard')).lower() == 'true' and str(c.get('status', 'A')) == 'A']\n        if cards:\n            vars['cards_json'] = json.dumps([{'n': i + 1, 'number': c.get('cardNumber'), 'last4': c.get('cardNumberLast4'), 'name': c.get('productName') or ''} for i, c in enumerate(cards)])\n            vars['cards_count'] = str(len(cards))\n            lines = []\n            names = []\n            for i, c in enumerate(cards):\n                nm = (c.get('productName') or '').strip()\n                lines.append(str(i + 1) + '. ' + (nm if nm else 'isimsiz kart') + ', sonu ' + sp(c.get('cardNumberLast4')))\n                if nm and nm not in names:\n                    names.append(nm)\n            vars['cards_text'] = '\\n'.join(lines)\n            ex = ' veya '.join(names[:2])\n            vars['select_text'] = 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + ex + ' diyebilirsiniz.' if ex else 'Hangi kartınızın borcunu öğrenmek istersiniz? Sonu kaç ile biten kart?'\n            vars['card_choice'] = '1' if len(cards) == 1 else '0'\n            vars['route'] = 'single' if len(cards) == 1 else 'multi'\n        else:\n            vars['route'] = 'none'\n    elif code == 'FB_IVR_CHANNEL_102' or str(result.get('status_code')) == '404':\n        vars['route'] = 'none'\nexcept Exception:\n    vars['route'] = 'error'\n"
    }
   ],
   "transitions": [
