     "post_process_code": "O = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']\nMO = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']\ndef dt(s):\n    d, m, y = str(s).split('.')\n    return str(int(d)) + ' ' + MO[int(m) - 1] + ' ' + y\ntry:\n    b = result.get('data')\n    data = b.get('data') if isinstance(b, dict) else None\n    if isinstance(data, dict) and data.get('statementWeek') is not None:\n        w = int(data.get('statementWeek'))\n        nm = (data.get('productName') or '').strip() or 'Sonu ' + str(data.get('cardNumberLast4'))\n        rel = (data.get('relatedCardProductName') or '').strip() or 'diğer'\n        rt = str(data.get('relationType') or '').strip()\n        if rt == 'M':\n            vars['joint_text'] = 'Bu değişiklik kartınıza bağlı ' + rel + ' kartınızı da etkileyecek.'\n        elif rt == 'C':\n            vars['joint_text'] = 'Bu değişiklik kartınızın bağlı olduğu ' + rel + ' kartınızı da etkileyecek.'\n        else:\n            vars['joint_text'] = ''\n        txt = nm + ' kartınızın hesap kesim tarihi her ayın ' + O[w] + ' haftası olarak tanımlı.'\n        if rt in ('M', 'C'):\n            txt += ' Bu kartınız ' + rel + ' kartınızla aynı ekstreyi paylaşıyor.'\n        txt += ' Bir sonraki hesap kesim tarihiniz ' + dt(data.get('nextStatementDate')) + ', son ödeme tarihiniz ' + dt(data.get('nextLastPayDate')) + '. Hesap kesim tarihinizi değiştirmek ister misiniz?'\n        others = [str(i) + '.' for i in (1, 2, 3, 4) if i != w]\n        opt = 'Hesap kesim tarihinizi ayın ' + ', '.join(others[:-1]) + ' ya da ' + others[-1] + ' haftasına alabilirim. Hangisini tercih edersiniz?'\n        data['week_text'] = txt\n        data['options_text'] = opt\n        data['what_to_do_next'] = 'Say week_text word for word. If the caller says yes, say options_text word for word. Offer only those weeks.'\n    elif isinstance(b, dict):\n        b['what_to_do_next'] = 'Say exactly: Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum. Then call end_call.'\nexcept Exception:\n    pass\n"
