     "function": {
      "name": "cards.balance",
      "handler": "__function__:api_call",
      "description": "Get the statement debt of the chosen card.",
      "parameters": {
       "type": "object",
       "properties": {
        "url": {"type": "string", "default": "https://thus-soccer-step-asks.trycloudflare.com/voice/v1/cards.balance"},
